const response = $input.first();
const html = response.json.data || response.data || response.body || '';
const headers = response.json.headers || response.headers || {};

if (!html || typeof html !== 'string') {
  return { error: 'No HTML data received' };
}

let setCookie = headers['set-cookie'] || headers['Set-Cookie'] || [];
if (!Array.isArray(setCookie)) setCookie = [setCookie];
const cookieStr = setCookie.map((c) => c.split(';')[0]).join('; ');

const patterns = [
  /name="__RequestVerificationToken"[^>]*value="([^"]+)"/i,
  /value="([^"]+)"[^>]*name="__RequestVerificationToken"/i,
  /__RequestVerificationToken.*?value="([^"]+)"/
];
let tokenMatch;
for (let pattern of patterns) {
  tokenMatch = html.match(pattern);
  if (tokenMatch) break;
}
if (!tokenMatch || !tokenMatch[1]) {
  return { error: 'Token CSRF no encontrado' };
}
return { csrfToken: tokenMatch[1], cookie: cookieStr };

const response = $input.first();
let html = response.json.data || response.data || response.body || '';
if (!html || typeof html !== 'string') {
  return { success: false, error: 'No HTML', polizas: [] };
}
const tableMatch = html.match(/<table[^>]*>([\s\S]*?)<\/table>/);
if (!tableMatch) {
  return { success: false, error: 'Table not found', polizas: [] };
}
const polizas = [];
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/g;
let rowMatch;
while ((rowMatch = rowRegex.exec(tableMatch[1])) !== null) {
  const row = rowMatch[1];
  const cellRegex = /<td[^>]*>([\s\S]*?)<\/td>/g;
  const cells = [];
  let cellMatch;
  while ((cellMatch = cellRegex.exec(row)) !== null) {
    let content = cellMatch[1].replace(/<[^>]*>/g, '').trim();
    cells.push(content);
  }
  if (cells.length < 28) continue;
  const ramo = cells[5] || '';
  const poliza = cells[6] || '';
  const endoso = cells[7] || '';
  const motivo = cells[9] || '';
  const productor = cells[13] || '';
  const idCotizacion = cells[27] || '';
  const motivos_excluir = ['Cambio forma de pago'];
  const productores_excluir = ['FASANELLA', 'LIJO', 'CALARCO', 'MAGNAGHI'];
  let excluir = false;
  if (motivos_excluir.some(m => motivo.toUpperCase().includes(m.toUpperCase()))) excluir = true;
  if (productores_excluir.some(p => productor.toUpperCase().includes(p.toUpperCase()))) excluir = true;
  if (!excluir && poliza && idCotizacion) {
    polizas.push({ramo, poliza, endoso, productor, motivo, idCotizacion});
  }
}
return { success: true, polizas };

const response = $input.first();
let html = response.json.data || response.data || response.body || '';
if (!html) return { calle: '', altura: '', provincia: '', sumaAsegurada: '' };
const riesgosMatch = html.match(/<table[^>]*>([\s\S]*?)<\/table>/);
if (!riesgosMatch) return { calle: '', altura: '', provincia: '', sumaAsegurada: '' };
const tableHtml = riesgosMatch[1];
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/g;
let rowMatch;
let calle = '', altura = '', provincia = '', sumaAsegurada = '';
while ((rowMatch = rowRegex.exec(tableHtml)) !== null) {
  const row = rowMatch[1];
  const cellRegex = /<td[^>]*>([\s\S]*?)<\/td>/g;
  const cells = [];
  let cellMatch;
  while ((cellMatch = cellRegex.exec(row)) !== null) {
    let content = cellMatch[1].replace(/<[^>]*>/g, '').trim();
    cells.push(content);
  }
  if (cells.length > 0 && cells[0].includes('INCENDIO EDIFICIO')) {
    sumaAsegurada = cells[2] || '';
  }
  if (cells.length >= 7) {
    calle = cells[6] || calle;
    altura = cells[7] || altura;
    provincia = cells[4] || provincia;
  }
}
return { calle, altura, provincia, sumaAsegurada };

const data = $input.all()[0];
const risks = $input.all()[1] || {};
return {
  Productor: data.productor,
  Poliza: data.poliza,
  Endoso: data.endoso,
  Calle: risks.calle || '',
  Altura: risks.altura || '',
  Provincia: risks.provincia || '',
  Suma_Asegurada: risks.sumaAsegurada || ''
};
